import re

def trump_detector(text: str) -> float:
    text = text.lower()
    vowels = 'aeiou'
    vowel_indices = [i for i, c in enumerate(text) if c in vowels]

    if not vowel_indices:
        return 0.0

    total_vowels = len(vowel_indices)
    extra_vowels = 0

    i = 0
    while i < len(vowel_indices):
        j = i + 1
        while j < len(vowel_indices) and text[vowel_indices[j]] == text[vowel_indices[i]] and (vowel_indices[j] - vowel_indices[j-1]) == 1:
            j += 1

        run_length = j - i
        if run_length > 1:
            extra_vowels += run_length - 1

        i = j

    if total_vowels == 0:
        return 0.0

    return round(extra_vowels / total_vowels, 2)
